    /// Every patient who has biology on file, with their readings and
    /// the words that describe their treatments — the input the reading
    /// rules need to answer the morning question: who do I call back?
    ///
    /// Two queries and a group-by rather than one per patient: a
    /// dashboard that opens in a tenth of a second is the whole point
    /// of it being on the dashboard.
    pub fn watchlist(&self) -> Result<Vec<WatchRow>, String> {
        let mut rows: std::collections::HashMap<i64, WatchRow> = std::collections::HashMap::new();
        {
            let mut stmt = self
                .conn
                .prepare(
                    "SELECT b.patient_id, p.first_name || ' ' || p.last_name,
                            b.code, b.value, b.taken_on
                     FROM biology b JOIN patients p ON p.id = b.patient_id
                     WHERE b.code <> ''
                     ORDER BY b.taken_on",
                )
                .map_err(|e| e.to_string())?;
            let found = stmt
                .query_map([], |r| {
                    Ok((
                        r.get::<_, i64>(0)?,
                        r.get::<_, String>(1)?,
                        r.get::<_, String>(2)?,
                        r.get::<_, f64>(3)?,
                        r.get::<_, String>(4)?,
                    ))
                })
                .map_err(|e| e.to_string())?;
            for row in found {
                let (id, name, code, value, date) = row.map_err(|e| e.to_string())?;
                let entry = rows.entry(id).or_insert_with(|| WatchRow {
                    patient_id: id,
                    patient_name: name,
                    readings: Vec::new(),
                    treatments: Vec::new(),
                    drugs: Vec::new(),
                });
                entry.readings.push((code, value, date));
            }
        }
        {
            let mut stmt = self
                .conn
                .prepare(
                    "SELECT pd.patient_id, p.first_name || ' ' || p.last_name,
                            d.name, d.dci, d.class, d.tags
                     FROM patient_drugs pd
                     JOIN drugs d ON d.id = pd.drug_id
                     JOIN patients p ON p.id = pd.patient_id",
                )
                .map_err(|e| e.to_string())?;
            let found = stmt
                .query_map([], |r| {
                    Ok((
                        r.get::<_, i64>(0)?,
                        r.get::<_, String>(1)?,
                        r.get::<_, String>(2)?,
                        r.get::<_, String>(3)?,
                        r.get::<_, String>(4)?,
                        r.get::<_, String>(5)?,
                    ))
                })
                .map_err(|e| e.to_string())?;
            for row in found {
                let (id, patient, name, dci, class, tags) = row.map_err(|e| e.to_string())?;
                // A file with treatments and no biology still has an
                // ordonnance to read: it belongs on the list too.
                let entry = rows.entry(id).or_insert_with(|| WatchRow {
                    patient_id: id,
                    patient_name: patient,
                    readings: Vec::new(),
                    treatments: Vec::new(),
                    drugs: Vec::new(),
                });
                entry
                    .drugs
                    .push((name.clone(), dci.clone(), class.clone(), tags.clone()));
                entry.treatments.extend(
                    [name, dci, class, tags]
                        .into_iter()
                        .filter(|t| !t.trim().is_empty()),
                );
            }
        }
        let mut out: Vec<WatchRow> = rows.into_values().collect();
        out.sort_by(|a, b| a.patient_name.cmp(&b.patient_name));
        Ok(out)
    }

    /// A patient's biology, most recent first; undated lines last.
    pub fn bio_results(&self, patient_id: i64) -> Result<Vec<BioResult>, String> {
        let mut stmt = self
            .conn
            .prepare(
                "SELECT id, code, label, value, unit, taken_on, remark
                 FROM biology WHERE patient_id = ?1
                 ORDER BY (taken_on = '') ASC, taken_on DESC, id DESC",
            )
            .map_err(|e| e.to_string())?;
        let rows = stmt
            .query_map([patient_id], |r| {
                Ok(BioResult {
                    id: r.get(0)?,
                    code: r.get(1)?,
                    label: r.get(2)?,
                    value: r.get(3)?,
                    unit: r.get(4)?,
                    taken_on: r.get(5)?,
                    remark: r.get(6)?,
                })
            })
            .map_err(|e| e.to_string())?;
        rows.collect::<Result<_, _>>().map_err(|e| e.to_string())
    }

    /// Record a result. Returns the new line's id.
    pub fn add_bio_result(&self, patient_id: i64, r: &BioResult) -> Result<i64, String> {
        self.conn
            .execute(
                "INSERT INTO biology (patient_id, code, label, value, unit, taken_on, remark)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                (
                    patient_id,
                    &r.code,
                    &r.label,
                    r.value,
                    &r.unit,
                    &r.taken_on,
                    &r.remark,
                ),
            )
            .map_err(|e| e.to_string())?;
        Ok(self.conn.last_insert_rowid())
    }

    /// Correct a result. Compare-and-set on the value and the date this
    /// PC displayed. Returns `false` when stale.
    pub fn update_bio_result(
        &self,
        new: &BioResult,
        expected: (f64, &str),
    ) -> Result<bool, String> {
        let changed = self
            .conn
            .execute(
                "UPDATE biology SET code = ?1, label = ?2, value = ?3, unit = ?4,
                                    taken_on = ?5, remark = ?6
                 WHERE id = ?7 AND value = ?8 AND taken_on = ?9",
                (
                    &new.code,
                    &new.label,
                    new.value,
                    &new.unit,
                    &new.taken_on,
                    &new.remark,
                    new.id,
                    expected.0,
                    expected.1,
                ),
            )
            .map_err(|e| e.to_string())?;
        Ok(changed == 1)
    }

    /// Remove a result. Compare-and-set on the value displayed.
    pub fn delete_bio_result(&self, id: i64, expected_value: f64) -> Result<bool, String> {
        let changed = self
            .conn
            .execute(
                "DELETE FROM biology WHERE id = ?1 AND value = ?2",
                (id, expected_value),
            )
            .map_err(|e| e.to_string())?;
        Ok(changed == 1)
    }

