    /// A first launch looks where an installed copy actually puts its
    /// base, and adopts the first one it finds — the launcher's
    /// directory before a stray copy beside the executable.
    #[test]
    fn a_first_launch_finds_the_base_the_launcher_left() {
        let root = std::env::temp_dir().join(format!("bpm-caddy-find-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let (launcher, portable) = (root.join("data/bpm-caddy"), root.join("usb"));
        std::fs::create_dir_all(&launcher).unwrap();
        std::fs::create_dir_all(&portable).unwrap();
        let order = || vec![launcher.clone(), portable.clone()];

        // Nothing anywhere: nothing to adopt, and the operator is shown
        // the default path rather than a base picked at random.
        assert_eq!(first_db_in(order()), None);

        // Only the portable copy exists: that is the answer.
        let carried = portable.join(DB_FILE_NAME);
        std::fs::write(&carried, b"pas vraiment une base").unwrap();
        assert_eq!(first_db_in(order()), Some(carried.clone()));

        // With both, the launcher's wins: it is the installed one.
        let installed = launcher.join(DB_FILE_NAME);
        std::fs::write(&installed, b"pas vraiment une base").unwrap();
        assert_eq!(first_db_in(order()), Some(installed));

        // A *directory* of that name is not a base.
        let _ = std::fs::remove_dir_all(&launcher);
        std::fs::create_dir_all(launcher.join(DB_FILE_NAME)).unwrap();
        assert_eq!(first_db_in(order()), Some(carried));

        let _ = std::fs::remove_dir_all(&root);
    }

    /// « Synchroniser le contenu de référence » — every seed this
    /// version ships, in the order the About page runs them.
    ///
    /// Two things are asserted, and they are the whole contract. It is
    /// **idempotent**: a base already at this version gains nothing from
    /// a second pass, so the button can be pressed twice without
    /// doubling anything. And it **never rewrites the team's own text**:
    /// a fiche the officine has edited comes out of the sync exactly as
    /// it went in, because the reference content fills gaps and does not
    /// correct pharmacists.
    #[test]
    fn synchronising_the_reference_content_fills_gaps_and_rewrites_nothing() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-sync-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = Db::open(&dir.join("live.db"), "secret").unwrap();

        // A base as a first unlock leaves it.
        db.seed_drugs_if_empty().unwrap();
        let sync = |db: &Db| -> usize {
            db.seed_missing_drugs().unwrap()
                + db.fill_starter_details().unwrap()
                + db.seed_posologies().unwrap()
                + db.seed_conduite().unwrap()
                + db.refresh_toxicity().unwrap()
                + db.seed_preparations().unwrap()
                + db.seed_dispositifs().unwrap()
                + db.seed_protocols().unwrap()
        };

        // The officine has written on one fiche, in a field the seeds
        // fill: what it wrote has to survive every pass.
        let mine = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name.eq_ignore_ascii_case("Eliquis"))
            .expect("Eliquis est une fiche de départ");
        let mut edited = mine.clone();
        edited.iup = "NOTRE TEXTE À NOUS".to_owned();
        edited.missed_dose = "NOTRE CONDUITE".to_owned();
        edited.toxicity = "NOTRE TOXICITÉ".to_owned();
        assert!(db.update_drug(&edited, &mine).unwrap());

        sync(&db);
        // Pressing it again is a no-op: nothing left to fill.
        assert_eq!(sync(&db), 0, "la synchronisation doit être idempotente");

        let after = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.id == mine.id)
            .unwrap();
        assert_eq!(after.iup, "NOTRE TEXTE À NOUS");
        assert_eq!(after.missed_dose, "NOTRE CONDUITE");
        assert_eq!(after.toxicity, "NOTRE TOXICITÉ");

        // And the content that travels with the binary is in the base.
        assert!(!db.preparations().unwrap().is_empty());
        assert!(!db.dispositifs().unwrap().is_empty());
        assert!(!db.protocols().unwrap().is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// An agenda entry drawn as a span on the day plan: the end hour is
    /// kept when it is after the start and dropped when it is not.
    ///
    /// A block drawn upside down is worse than a block one row tall, and
    /// the drag that produces these can end above where it began — the
    /// pointer goes back up as easily as down.
    #[test]
    fn an_entry_keeps_an_end_hour_only_when_it_is_after_the_start() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-span-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = Db::open(&dir.join("live.db"), "secret").unwrap();
        let day = db.today_iso().unwrap();
        let add = |time: &str, end: &str, title: &str| {
            db.add_event_span(&day, time, end, title, EventCategory::Formation, 0, "")
                .unwrap()
        };
        add("09:00", "10:30", "plage");
        add("11:00", "10:00", "à l'envers");
        add("14:00", "14:00", "sans durée");
        add("", "", "sans heure");
        let mut got: Vec<(String, String)> = db
            .events_between(&day, &day)
            .unwrap()
            .into_iter()
            .map(|e| (e.title, e.end_time))
            .collect();
        got.sort();
        assert_eq!(
            got,
            [
                ("plage".to_owned(), "10:30".to_owned()),
                ("sans durée".to_owned(), String::new()),
                ("sans heure".to_owned(), String::new()),
                ("à l'envers".to_owned(), String::new()),
            ]
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The list the navigator's A–Z tree is built from: sorted the way a
    /// human reads, accents folded in with their letter.
    ///
    /// SQLite's `COLLATE NOCASE` is ASCII-only, so « Élugan » came back
    /// after Z — which would have opened a second E drawer at the end of
    /// the alphabet, with one fiche in it that nobody would look for
    /// there.
    #[test]
    fn the_drug_list_sorts_with_accents_folded_in() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-sort-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = Db::open(&dir.join("live.db"), "secret").unwrap();
        for name in ["Zovirax", "elugan", "Élugan", "Aclasta", "Eliquis"] {
            db.add_drug(name).unwrap();
        }
        let names: Vec<String> = db
            .drugs()
            .unwrap()
            .into_iter()
            .map(|d| d.name)
            .filter(|n| ["Zovirax", "elugan", "Élugan", "Aclasta", "Eliquis"].contains(&n.as_str()))
            .collect();
        assert_eq!(
            names,
            ["Aclasta", "Eliquis", "elugan", "Élugan", "Zovirax"],
            "{names:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn date_roundtrip() {
        assert_eq!(parse("03/07/1958").unwrap(), "1958-07-03");
        assert_eq!(format_french_date("1958-07-03"), "03/07/1958");
        assert!(parse("1958-07-03").is_err() || parse("31/12/1999").is_ok());
        assert!(parse("32/01/2000").is_err());
        assert!(parse("abc").is_err());
    }

    #[test]
    fn yearly_quota_rule_cycles_every_twelve_months() {
        let d = |s: &str| s.to_owned();
        // No rule / no history: always allowed.
        assert_eq!(rule_next_allowed(&[], "2026-08-24", 3, 12), None);
        assert_eq!(
            rule_next_allowed(&[d("2026-01-01")], "2026-08-24", 0, 12),
            None
        );
        // Two of three used this cycle: allowed.
        let two = [d("2026-01-10"), d("2026-03-01")];
        assert_eq!(rule_next_allowed(&two, "2026-08-24", 3, 12), None);
        // Quota full: blocked until 12 months after the cycle's first act.
        let three = [d("2026-01-10"), d("2026-03-01"), d("2026-06-15")];
        assert_eq!(
            rule_next_allowed(&three, "2026-08-24", 3, 12),
            Some(d("2027-01-10"))
        );
        // On/after that date, the "entretien nouvelle année" is allowed.
        assert_eq!(rule_next_allowed(&three, "2027-01-10", 3, 12), None);
        // A second cycle fills up relative to ITS first act, not the
        // original one.
        let cycle2 = [
            d("2026-01-10"),
            d("2026-03-01"),
            d("2026-06-15"),
            d("2027-02-01"), // first act of cycle 2
            d("2027-04-01"),
            d("2027-05-01"),
        ];
        assert_eq!(
            rule_next_allowed(&cycle2, "2027-06-01", 3, 12),
            Some(d("2028-02-01"))
        );
        assert_eq!(rule_next_allowed(&cycle2, "2028-02-01", 3, 12), None);
        // Leap-day cycle start clamps sanely.
        assert_eq!(add_one_year("2028-02-29"), "2029-02-28");
        assert_eq!(add_one_year("2026-08-24"), "2027-08-24");
    }

    #[test]
    fn weekdays_are_correct() {
        assert_eq!(weekday_fr("2026-01-01"), Some("jeudi"));
        assert_eq!(weekday_fr("2026-08-24"), Some("lundi"));
        assert_eq!(weekday_fr("2000-01-01"), Some("samedi"));
        assert_eq!(weekday_fr("1958-07-03"), Some("jeudi"));
        assert_eq!(weekday_fr("pas-une-date"), None);
    }

    /// The ordonnance's adjuvant list is whatever the base carries
    /// under the tag — adding a product is adding a card, not editing
    /// the app.
    /// A posology line names its card by brand, and the seeder groups
    /// consecutive lines under one drug: a name that matches nothing is
    /// silently dropped, and a brand split into two runs loses the
    /// second. Both are invisible at the counter, so they are checked
    /// here.
    /// A spot-check that the new lines actually reach a seeded base and
    /// come back in the order they were written.
    #[test]
    fn the_new_posology_lines_seed_onto_their_cards() {
        // A directory of its own: the tests in this binary share one
        // process id, so two using the same name race each other.
        let dir = std::env::temp_dir().join(format!("bpm-caddy-newposo-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("newposo.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        db.seed_drugs_if_empty().unwrap();
        db.seed_posologies().unwrap();

        for brand in [
            "Xalatan",
            "Maxalt",
            "Malarone",
            "Nasonex",
            "Coltramyl",
            "Kredex",
            "Nicotinell",
            "Zocor",
            "Lipur",
            "Engerix B",
        ] {
            let card = db
                .drugs()
                .unwrap()
                .into_iter()
                .find(|d| d.name == brand)
                .unwrap_or_else(|| panic!("{brand} absent du référentiel"));
            let rows = db.posologies(card.id).unwrap();
            assert!(!rows.is_empty(), "{brand} : aucune posologie semée");
            let expected: Vec<&str> = STARTER_POSOLOGIES
                .iter()
                .filter(|(b, ..)| *b == brand)
                .map(|(_, indication, ..)| *indication)
                .collect();
            assert_eq!(
                rows.iter()
                    .map(|r| r.indication.as_str())
                    .collect::<Vec<_>>(),
                expected,
                "{brand} : ordre des lignes"
            );
        }
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn every_posology_names_a_real_card_and_stays_in_one_run() {
        let names: std::collections::HashSet<&str> =
            STARTER_DRUGS.iter().map(|(n, ..)| *n).collect();
        let mut seen_runs: std::collections::HashMap<&str, usize> = Default::default();
        let mut previous = "";
        for (brand, indication, posologie, remarque) in STARTER_POSOLOGIES {
            assert!(
                names.contains(brand),
                "posologie « {indication} » rattachée à « {brand} », qui n'est pas une fiche"
            );
            assert!(!indication.trim().is_empty(), "{brand} : indication vide");
            assert!(!posologie.trim().is_empty(), "{brand} : posologie vide");
            assert!(!remarque.trim().is_empty(), "{brand} : remarque vide");
            if *brand != previous {
                *seen_runs.entry(brand).or_default() += 1;
                previous = brand;
            }
        }
        let split: Vec<&&str> = seen_runs
            .iter()
            .filter(|(_, runs)| **runs > 1)
            .map(|(brand, _)| brand)
            .collect();
        assert!(
            split.is_empty(),
            "lignes non contiguës, la seconde série serait perdue : {split:?}"
        );
    }

    /// The monograph set is the app's main clinical asset: every card
    /// must carry a full monograph and its sources. A card added
    /// without them would render as a page of blank headings at the
    /// counter, which is worse than no card at all.
    #[test]
    fn every_starter_card_carries_a_sourced_monograph() {
        // The reference base only ever grows: a fiche removed is a
        // question the counter can no longer answer from the app.
        assert!(
            STARTER_DRUGS.len() >= 831,
            "{} fiches livrées, il y en avait huit cent trente et une",
            STARTER_DRUGS.len()
        );
        let names: std::collections::HashSet<&str> =
            STARTER_DRUGS.iter().map(|(n, ..)| *n).collect();
        let detailed: std::collections::HashSet<&str> =
            STARTER_DETAILS.iter().map(|d| d.name).collect();
        assert_eq!(names.len(), STARTER_DRUGS.len(), "nom de fiche en double");
        let missing: Vec<&&str> = names.difference(&detailed).collect();
        assert!(missing.is_empty(), "fiches sans monographie : {missing:?}");
        let orphan: Vec<&&str> = detailed.difference(&names).collect();
        assert!(orphan.is_empty(), "monographies sans fiche : {orphan:?}");

        // The clinical body of a monograph, and the sources behind it.
        // `status`, `smr` and `forms` are deliberately not in this list:
        // they are the officine's to fill, and empty ones simply do not
        // render.
        type Field = (&'static str, fn(&StarterDetail) -> &'static str);
        let required: [Field; 13] = [
            ("indications", |d| d.indications),
            ("mechanism", |d| d.mechanism),
            ("dosage", |d| d.dosage),
            ("contraindications", |d| d.contraindications),
            ("ddi", |d| d.ddi),
            ("adverse", |d| d.adverse),
            ("monitoring", |d| d.monitoring),
            ("iup", |d| d.iup),
            ("half_life", |d| d.half_life),
            ("elimination", |d| d.elimination),
            ("renal", |d| d.renal),
            ("pregnancy", |d| d.pregnancy),
            ("sources", |d| d.sources),
        ];
        for detail in STARTER_DETAILS {
            for (label, get) in required {
                assert!(
                    !get(detail).trim().is_empty(),
                    "{} : le champ « {label} » est vide",
                    detail.name
                );
            }
            assert!(
                !detail.tags.trim().is_empty(),
                "{} : aucune étiquette",
                detail.name
            );
        }
    }

    #[test]
    fn drugs_are_found_by_an_exact_tag_among_several() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-tag-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("tag.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();

        let tagged = |name: &str, tags: &str| {
            let id = db.add_drug(name).unwrap();
            let mut d = db
                .drugs()
                .unwrap()
                .into_iter()
                .find(|d| d.id == id)
                .unwrap();
            let seen = d.clone();
            d.tags = tags.to_owned();
            assert!(db.update_drug(&d, &seen).unwrap());
            id
        };
        let lactibiane = tagged("Lactibiane", "probiotique, flore intestinale");
        // Leading space and different case must still match.
        tagged("Lactéol", "antidiarrhéique,  Probiotique");
        // A tag that merely *contains* the word is not the same tag.
        tagged("Gynophilus", "probiotique vaginal");
        tagged("Doliprane", "antalgique");

        let found = db.drugs_with_tag("probiotique").unwrap();
        let names: Vec<&str> = found.iter().map(|d| d.name.as_str()).collect();
        assert!(names.contains(&"Lactibiane"), "{names:?}");
        assert!(names.contains(&"Lactéol"), "{names:?}");
        assert!(!names.contains(&"Gynophilus"), "{names:?}");
        assert!(!names.contains(&"Doliprane"), "{names:?}");

        // The card's own posology lines are what the box offers.
        db.add_posologie(lactibiane, "Antibiothérapie", "1 gélule par jour", "")
            .unwrap();
        assert_eq!(db.posologies(lactibiane).unwrap().len(), 1);

        // An empty tag matches nothing rather than everything.
        assert!(db.drugs_with_tag("  ").unwrap().is_empty());
        assert!(db.drugs_with_tag("probio").unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn age_counts_completed_years_around_the_birthday() {
        // The day before, the day of, and the day after a birthday.
        assert_eq!(age_on("1958-07-03", "2026-07-02"), Some(67));
        assert_eq!(age_on("1958-07-03", "2026-07-03"), Some(68));
        assert_eq!(age_on("1958-07-03", "2026-07-04"), Some(68));
        // 29 February: the age ticks over on 1 March in a common year.
        assert_eq!(age_on("2000-02-29", "2026-02-28"), Some(25));
        assert_eq!(age_on("2000-02-29", "2026-03-01"), Some(26));
        assert_eq!(age_on("2026-01-01", "2026-08-26"), Some(0));
        // A birth date after today, or a malformed one, has no age.
        assert_eq!(age_on("2030-01-01", "2026-08-26"), None);
        assert_eq!(age_on("", "2026-08-26"), None);
    }

    #[test]
    fn the_carnet_de_vaccination_round_trips_and_is_compare_and_set() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-vacc-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("vacc.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();

        let dose = Vaccination {
            code: "DTP".to_owned(),
            label: "dTP — diphtérie, tétanos, poliomyélite".to_owned(),
            dose: "Rappel".to_owned(),
            given_on: "2026-08-26".to_owned(),
            lot: "K1234".to_owned(),
            site: "deltoïde G".to_owned(),
            operator: "CL".to_owned(),
            ..Default::default()
        };
        let id = db.add_vaccination(pid, &dose).unwrap();
        // A second, older line: the carnet reads newest first.
        db.add_vaccination(
            pid,
            &Vaccination {
                code: "GRIPPE".to_owned(),
                label: "Grippe saisonnière".to_owned(),
                given_on: "2025-10-04".to_owned(),
                ..Default::default()
            },
        )
        .unwrap();
        let lines = db.vaccinations(pid).unwrap();
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[0].code, "DTP");
        assert_eq!(lines[0].lot, "K1234");
        assert_eq!(lines[1].code, "GRIPPE");

        // Correcting the lot succeeds against the values displayed…
        let mut fixed = lines[0].clone();
        fixed.lot = "K9999".to_owned();
        assert!(db
            .update_vaccination(id, &fixed, &lines[0].label, &lines[0].given_on)
            .unwrap());
        // …and fails against a date another PC has already changed.
        assert!(!db
            .update_vaccination(id, &fixed, &lines[0].label, "1999-01-01")
            .unwrap());

        assert!(!db.delete_vaccination(id, "un autre libellé").unwrap());
        assert!(db.delete_vaccination(id, &lines[0].label).unwrap());
        assert_eq!(db.vaccinations(pid).unwrap().len(), 1);

        // Destinations: adding the same country twice moves the date
        // instead of duplicating the line.
        db.add_travel(pid, "ML", "2026-11-02").unwrap();
        db.add_travel(pid, "TH", "").unwrap();
        db.add_travel(pid, "ML", "2026-12-01").unwrap();
        let travels = db.travels(pid).unwrap();
        assert_eq!(travels.len(), 2);
        assert_eq!(travels[0].country, "ML");
        assert_eq!(travels[0].depart_on, "2026-12-01");
        // The undated destination sorts last.
        assert_eq!(travels[1].country, "TH");
        assert!(db.remove_travel(pid, "ML").unwrap());
        assert!(!db.remove_travel(pid, "ML").unwrap());

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn week_dates_run_monday_to_sunday_around_today() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-week-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("week.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();

        let week = db.week_dates(0).unwrap();
        assert_eq!(week.len(), 7);
        assert_eq!(weekday_fr(&week[0]), Some("lundi"));
        assert_eq!(weekday_fr(&week[6]), Some("dimanche"));
        let today = db.today_iso().unwrap();
        assert!(week.contains(&today));
        // Next week starts right after this week's Sunday.
        let next = db.week_dates(1).unwrap();
        assert!(next[0] > week[6]);
        assert_eq!(weekday_fr(&next[0]), Some("lundi"));

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn impossible_dates_are_rejected() {
        assert!(parse("31/02/2000").is_err());
        assert!(parse("31/04/2020").is_err());
        assert!(parse("29/02/2001").is_err());
        // 2000 is a leap year (divisible by 400), 1900 is not.
        assert!(parse("29/02/2000").is_ok());
        assert!(parse("29/02/1900").is_err());
        assert!(parse("30/04/2020").is_ok());
        assert!(parse("31/12/1999").is_ok());
    }

    #[test]
    fn compact_date_shorthand() {
        use YearHint::{Future, Past};
        // Today typed at the counter: 230826 → 23/08/2026.
        assert_eq!(
            parse_french_date("230826", 2026, Future).unwrap(),
            "2026-08-23"
        );
        assert_eq!(
            parse_french_date("1908", 2026, Future).unwrap(),
            "2026-08-19"
        );
        assert_eq!(
            parse_french_date("19082026", 2026, Future).unwrap(),
            "2026-08-19"
        );
        // Birth dates never land in the future ("49" → 1949, newborn "26" → 2026)…
        assert_eq!(
            parse_french_date("110249", 2026, Past).unwrap(),
            "1949-02-11"
        );
        assert_eq!(
            parse_french_date("030726", 2026, Past).unwrap(),
            "2026-07-03"
        );
        // …while appointments always expand to 20xx.
        assert_eq!(
            parse_french_date("110249", 2026, Future).unwrap(),
            "2049-02-11"
        );
        // Yearless forms are for RDVs only: a birth date without a year
        // is more likely truncated than a newborn — rejected.
        assert!(parse_french_date("1908", 2026, Past).is_err());
        assert!(parse_french_date("19/08", 2026, Past).is_err());
        // Separator forms take the same two-digit and day/month shorthand.
        assert_eq!(
            parse_french_date("3/7/58", 2026, Past).unwrap(),
            "1958-07-03"
        );
        assert_eq!(
            parse_french_date("19/08", 2026, Future).unwrap(),
            "2026-08-19"
        );
        // Shorthand is still validated.
        assert!(parse_french_date("300226", 2026, Future).is_err()); // 30/02
        assert!(parse_french_date("12345", 2026, Future).is_err()); // wrong length
        assert!(parse_french_date("1913", 2026, Future).is_err()); // month 13
    }

    #[test]
    fn interview_pipeline_is_strictly_ordered() {
        let mut state = InterviewState::Identified;
        let mut seen = vec![state];
        while let Some(next) = state.next() {
            state = next;
            seen.push(state);
        }
        assert_eq!(seen, InterviewState::ALL);
        assert_eq!(state, InterviewState::Billed);
        assert_eq!(state.next(), None);
        // Round-trip through the storage representation.
        for s in InterviewState::ALL {
            assert_eq!(InterviewState::parse(s.as_str()), Some(s));
        }
        for k in InterviewKind::ALL {
            assert_eq!(InterviewKind::parse(k.as_str()), Some(k));
        }
    }

    #[test]
    fn interviews_advance_and_persist() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-itest-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("interviews.db");
        let _ = std::fs::remove_file(&path);

        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Martin", "Claire", "1949-02-11").unwrap();
        let iid = db.add_interview(pid, InterviewKind::Bpm).unwrap();

        let loaded = db.interviews_for(pid).unwrap();
        assert_eq!(loaded.len(), 1);
        assert_eq!(loaded[0].state, InterviewState::Identified);
        assert_eq!(
            db.interview_dates_for(pid, InterviewKind::Bpm)
                .unwrap()
                .len(),
            1
        );
        assert!(db
            .interview_dates_for(pid, InterviewKind::Aod)
            .unwrap()
            .is_empty());

        db.advance_interview(iid, InterviewState::Identified)
            .unwrap();
        let loaded = db.interviews_for(pid).unwrap();
        assert_eq!(loaded[0].state, InterviewState::Scheduled);

        // A misclicked advance can be stepped back.
        db.regress_interview(iid, InterviewState::Scheduled)
            .unwrap();
        let loaded = db.interviews_for(pid).unwrap();
        assert_eq!(loaded[0].state, InterviewState::Identified);
        // Regressing the first state is a harmless no-op.
        db.regress_interview(iid, InterviewState::Identified)
            .unwrap();
        assert_eq!(
            db.interviews_for(pid).unwrap()[0].state,
            InterviewState::Identified
        );

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn hours_are_read_the_fast_way() {
        // The counter types the hour the short way; the field only
        // accepts what is a plausible time of day.
        assert_eq!(parse_hour("9").as_deref(), Some("09:00"));
        assert_eq!(parse_hour("9h").as_deref(), Some("09:00"));
        assert_eq!(parse_hour("930").as_deref(), Some("09:30"));
        assert_eq!(parse_hour("9h30").as_deref(), Some("09:30"));
        assert_eq!(parse_hour("09:30").as_deref(), Some("09:30"));
        assert_eq!(parse_hour("1615").as_deref(), Some("16:15"));
        assert_eq!(parse_hour("16 h 15").as_deref(), Some("16:15"));
        // Nonsense is refused rather than stored.
        assert_eq!(parse_hour("25h"), None);
        assert_eq!(parse_hour("1290"), None);
        assert_eq!(parse_hour("plus tard"), None);
        assert_eq!(parse_hour(""), None);
    }

    #[test]
    fn appointments_are_ordered_by_hour_within_a_day() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-hours-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("hours.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let mut ids = Vec::new();
        for (kind, time) in [
            (InterviewKind::Bpm, "16:15"),
            (InterviewKind::Aod, ""),
            (InterviewKind::Asthme, "09:30"),
        ] {
            let id = db.add_interview(pid, kind).unwrap();
            db.set_scheduled_date(id, Some("2030-05-12"), None).unwrap();
            if !time.is_empty() {
                assert!(db.set_scheduled_time(id, time, "").unwrap());
            }
            ids.push(id);
        }
        // Timed rendez-vous come first, in order; the untimed one last.
        let times: Vec<String> = db
            .upcoming_appointments()
            .unwrap()
            .into_iter()
            .map(|a| a.time)
            .collect();
        assert_eq!(times, vec!["09:30", "16:15", ""]);
        // The hour is compare-and-set like the date.
        assert!(!db.set_scheduled_time(ids[0], "10:00", "08:00").unwrap());
        assert!(db.set_scheduled_time(ids[0], "10:00", "16:15").unwrap());
        // Clearing it is a write like any other.
        assert!(db.set_scheduled_time(ids[0], "", "10:00").unwrap());
        assert_eq!(db.interviews_for(pid).unwrap().len(), 3);

        let _ = std::fs::remove_file(&path);
    }

    /// « Autres traitements anticancéreux » : the memo lets the
    /// sequence be finalised before the twelve months are out, so a
    /// completed sequence opens the next one straight away.
    #[test]
    fn the_autres_anticancereux_sequence_may_close_early() {
        let dates: Vec<String> = [
            "2026-01-05",
            "2026-02-02",
            "2026-03-02",
            "2026-04-06",
            "2026-05-04",
        ]
        .iter()
        .map(|d| (*d).to_owned())
        .collect();
        let none = vec![false; dates.len()];
        // Long cours: the three acts of année 1 spread over the year,
        // and the fourth stays inside it — the year is not over.
        assert_eq!(
            cycle_positions_for(InterviewKind::AnticancereuxLc, &dates, &none, 12),
            vec![(0, 0), (0, 1), (0, 2), (0, 3), (0, 4)]
        );
        // Autres : the sequence of année 1 holds three entretiens, then
        // the « années suivantes » sequences hold two.
        assert_eq!(
            cycle_positions_for(InterviewKind::AnticancereuxAutres, &dates, &none, 12),
            vec![(0, 0), (0, 1), (0, 2), (1, 0), (1, 1)]
        );
        assert!(InterviewKind::AnticancereuxAutres.sequence_may_finish_early());
        assert!(!InterviewKind::AnticancereuxLc.sequence_may_finish_early());
        assert!(!InterviewKind::Bpm.sequence_may_finish_early());
    }

    /// The memo's anticancéreux derogation: an entretien marked as
    /// following a treatment change opens a new sequence at once,
    /// always at the « années suivantes » tariff.
    #[test]
    fn a_treatment_change_opens_a_new_sequence() {
        let dates: Vec<String> = ["2026-01-05", "2026-03-02", "2026-05-04", "2026-07-06"]
            .iter()
            .map(|d| (*d).to_owned())
            .collect();
        // Without the marker, the four acts are one année 1 sequence.
        assert_eq!(
            cycle_positions(&dates, 12),
            vec![(0, 0), (0, 1), (0, 2), (0, 3)]
        );
        // The third act follows a treatment change: it restarts the
        // sequence, and the restart never lands back in année 1.
        let restarts = [false, false, true, false];
        assert_eq!(
            cycle_positions_with_restarts(&dates, &restarts, 12),
            vec![(0, 0), (0, 1), (1, 0), (1, 1)]
        );
        // A second change in a later sequence stays on the « années
        // suivantes » row rather than climbing a year each time.
        let restarts = [false, true, false, true];
        assert_eq!(
            cycle_positions_with_restarts(&dates, &restarts, 12),
            vec![(0, 0), (1, 0), (1, 1), (1, 0)]
        );
        // The derogation belongs to the anticancéreux themes only.
        assert!(InterviewKind::AnticancereuxLc.allows_treatment_change());
        assert!(InterviewKind::AnticancereuxAutres.allows_treatment_change());
        assert!(!InterviewKind::Bpm.allows_treatment_change());
        assert!(!InterviewKind::Aod.allows_treatment_change());
        // Année 1 is the stricter case; long cours needs one thematic
        // after the change where « autres » needs two.
        assert_eq!(
            InterviewKind::AnticancereuxLc.treatment_change_minimums(true),
            (2, 2)
        );
        assert_eq!(
            InterviewKind::AnticancereuxLc.treatment_change_minimums(false),
            (1, 1)
        );
        assert_eq!(
            InterviewKind::AnticancereuxAutres.treatment_change_minimums(false),
            (1, 2)
        );
    }

    #[test]
    fn cycles_follow_the_configured_length() {
        // Six-month cycles: the third act opens a new cycle.
        let dates: Vec<String> = ["2026-01-10", "2026-03-10", "2026-08-10", "2026-10-01"]
            .iter()
            .map(|s| (*s).to_owned())
            .collect();
        assert_eq!(cycle_ranks_months(&dates, 6), vec![0, 1, 0, 1]);
        // The same dates over twelve months are one cycle then another.
        assert_eq!(cycle_ranks_months(&dates, 12), vec![0, 1, 2, 3]);
        // The quota rule uses the same segmentation.
        assert_eq!(
            rule_next_allowed(&dates[..2], "2026-04-01", 2, 6),
            Some("2026-07-10".to_owned())
        );
        assert_eq!(rule_next_allowed(&dates[..2], "2026-08-01", 2, 6), None);
        // add_months clamps the short months and February.
        assert_eq!(add_months("2026-01-31", 1), "2026-02-28");
        assert_eq!(add_months("2024-01-31", 1), "2024-02-29");
        assert_eq!(add_months("2026-08-25", 6), "2027-02-25");
        assert_eq!(add_months("2026-08-25", 12), add_one_year("2026-08-25"));
    }

    #[test]
    fn cycle_ranks_number_acts_within_each_yearly_cycle() {
        // Three acts in one année d'accompagnement, then a new cycle
        // (≥ 12 months after the first act of the previous one).
        let dates: Vec<String> = [
            "2026-01-10",
            "2026-04-10",
            "2026-09-10",
            "2027-02-01",
            "2027-06-01",
        ]
        .iter()
        .map(|s| (*s).to_owned())
        .collect();
        assert_eq!(cycle_ranks_months(&dates, 12), vec![0, 1, 2, 0, 1]);
        // The very first act of a base is always the entretien initial.
        assert_eq!(cycle_ranks_months(&["2026-08-24".to_owned()], 12), vec![0]);
        assert!(cycle_ranks_months(&[], 12).is_empty());
    }

    #[test]
    fn themes_are_compare_and_set_and_reach_the_export() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-theme-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("theme.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let id = db
            .add_interview_themed(pid, InterviewKind::Bpm, "Observance")
            .unwrap();
        assert_eq!(db.interviews_for(pid).unwrap()[0].theme, "Observance");
        // A write from a stale view is rejected, not applied.
        assert!(!db.set_theme(id, "Interactions", "Biologie / INR").unwrap());
        assert!(db.set_theme(id, "Interactions", "Observance").unwrap());
        let rows = db.export_rows(12).unwrap();
        assert_eq!(rows[0].theme, "Interactions");
        assert_eq!(rows[0].fee_rank, 0);
        // A second act of the same cycle is a suivi, and the summaries
        // agree with the export.
        db.add_interview(pid, InterviewKind::Bpm).unwrap();
        let mut ranks: Vec<usize> = db
            .export_rows(12)
            .unwrap()
            .iter()
            .map(|r| r.fee_rank)
            .collect();
        ranks.sort_unstable();
        assert_eq!(ranks, vec![0, 1]);
        let mut ranks: Vec<usize> = db
            .interview_summaries(12)
            .unwrap()
            .iter()
            .map(|s| s.fee_rank)
            .collect();
        ranks.sort_unstable();
        assert_eq!(ranks, vec![0, 1]);

        let _ = std::fs::remove_file(&path);
    }

    /// A biology result is recorded, corrected and removed like every
    /// other shared row: compare-and-set on what the screen displayed.
    #[test]
    fn a_biology_result_is_written_and_corrected() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-bio-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("bio.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let row = BioResult {
            id: 0,
            code: "K".to_owned(),
            label: "Kaliémie".to_owned(),
            value: 5.4,
            unit: "mmol/L".to_owned(),
            taken_on: "2026-08-20".to_owned(),
            remark: String::new(),
        };
        let id = db.add_bio_result(pid, &row).unwrap();
        let older = BioResult {
            value: 4.6,
            taken_on: "2026-05-14".to_owned(),
            ..row.clone()
        };
        db.add_bio_result(pid, &older).unwrap();
        // Most recent first.
        let all = db.bio_results(pid).unwrap();
        assert_eq!(all.len(), 2);
        assert_eq!(all[0].taken_on, "2026-08-20");
        // A correction from a stale view is refused.
        let mut fixed = all[0].clone();
        fixed.value = 4.9;
        assert!(!db.update_bio_result(&fixed, (9.9, "2026-08-20")).unwrap());
        assert!(db.update_bio_result(&fixed, (5.4, "2026-08-20")).unwrap());
        assert_eq!(db.bio_results(pid).unwrap()[0].value, 4.9);
        // And a delete from a stale view too.
        assert!(!db.delete_bio_result(id, 5.4).unwrap());
        assert!(db.delete_bio_result(id, 4.9).unwrap());
        assert_eq!(db.bio_results(pid).unwrap().len(), 1);
        // Deleting the patient takes the biology with it.
        db.delete_patient(pid).unwrap();
        assert!(db.bio_results(pid).unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    /// The dashboard's call list reads the whole base in two queries,
    /// and only ever speaks about files that have biology on them.
    #[test]
    fn the_watchlist_carries_each_patient_s_readings_and_treatments() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-watch-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("watch.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        // An empty base has nothing to say.
        assert!(db.watchlist().unwrap().is_empty());
        db.seed_drugs_if_empty().unwrap();
        let watched = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let quiet = db.add_patient("Martin", "Claire", "1949-02-11").unwrap();
        let coversyl = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name == "Coversyl")
            .expect("le Coversyl est dans la base de départ");
        db.add_patient_drug(watched, coversyl.id).unwrap();
        db.add_patient_drug(quiet, coversyl.id).unwrap();
        for (value, day) in [(4.6, "2026-05-14"), (5.4, "2026-08-20")] {
            db.add_bio_result(
                watched,
                &BioResult {
                    id: 0,
                    code: "K".to_owned(),
                    label: "Kaliémie".to_owned(),
                    value,
                    unit: "mmol/L".to_owned(),
                    taken_on: day.to_owned(),
                    remark: String::new(),
                },
            )
            .unwrap();
        }
        // A line written by hand carries no code and answers nothing:
        // it must not create a row of its own.
        db.add_bio_result(
            watched,
            &BioResult {
                id: 0,
                label: "Sérologie".to_owned(),
                value: 1.0,
                ..Default::default()
            },
        )
        .unwrap();
        let rows = db.watchlist().unwrap();
        // Both patients have a treatment, so both are on the list; only
        // one of them has biology.
        assert_eq!(rows.len(), 2);
        let row = rows
            .iter()
            .find(|r| r.patient_id == watched)
            .expect("le patient suivi est sur la liste");
        assert_eq!(
            rows.iter()
                .find(|r| r.patient_id == quiet)
                .map(|r| r.readings.len()),
            Some(0)
        );
        let rows = [row];
        assert_eq!(rows[0].readings.len(), 2);
        // Oldest first, so the reading rules keep the latest.
        assert_eq!(rows[0].readings[0].2, "2026-05-14");
        // The treatments come as words: brand, DCI, class and tags.
        assert!(rows[0].treatments.iter().any(|t| t == "Coversyl"));
        assert!(rows[0].treatments.iter().any(|t| t.contains("IEC")));

        let _ = std::fs::remove_file(&path);
    }

    /// The two counter answers a monograph was missing: what to do
    /// when a dose is missed, and what makes the patient consult.
    #[test]
    fn the_conduite_fills_the_cards_it_names_and_nothing_else() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-conduite-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("conduite.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        db.seed_drugs_if_empty().unwrap();
        let all = db.drugs().unwrap();
        // A good half of the base is covered by the class rules; the
        // rest is the specialities nobody has a general answer for.
        let filled = all.iter().filter(|d| !d.missed_dose.is_empty()).count();
        assert!(
            filled > all.len() / 3,
            "seulement {filled} fiches sur {} renseignées",
            all.len()
        );
        // Both fields go together: a card never says what to do without
        // saying what to watch for.
        for d in &all {
            assert_eq!(
                d.missed_dose.is_empty(),
                d.red_flags.is_empty(),
                "{} : une seule des deux conduites",
                d.name
            );
        }
        // The classes that carry the most risk are all covered.
        for name in ["Eliquis", "Previscan", "Levothyrox", "Glucophage", "Zocor"] {
            let card = all.iter().find(|d| d.name == name);
            if let Some(card) = card {
                assert!(
                    !card.missed_dose.is_empty(),
                    "{name} sans conduite en cas d'oubli"
                );
            }
        }
        // Running it again changes nothing, and does not even look at
        // the cards: the pass leaves a mark saying how many rules it
        // applied.
        assert_eq!(db.seed_conduite().unwrap(), 0);
        assert_eq!(
            db.seed_mark("conduite").unwrap().as_deref(),
            Some(STARTER_CONDUITE.len().to_string().as_str())
        );
        // And a card the team has written to is left alone.
        let mut edited = all
            .iter()
            .find(|d| !d.missed_dose.is_empty())
            .expect("au moins une fiche renseignée")
            .clone();
        let base = edited.clone();
        edited.missed_dose = "La conduite de l'officine.".to_owned();
        assert!(db.update_drug(&edited, &base).unwrap());
        db.seed_conduite().unwrap();
        let after = db.drugs().unwrap();
        let kept = after.iter().find(|d| d.id == edited.id).unwrap();
        assert_eq!(kept.missed_dose, "La conduite de l'officine.");
        // A field cleared on purpose stays cleared: the lock is what
        // says « we have decided about this one », not the emptiness.
        let base = kept.clone();
        let mut cleared = kept.clone();
        cleared.missed_dose = String::new();
        cleared.red_flags = String::new();
        assert!(db.update_drug(&cleared, &base).unwrap());
        db.seed_conduite().unwrap();
        let after = db.drugs().unwrap();
        let still = after.iter().find(|d| d.id == cleared.id).unwrap();
        assert_eq!(
            still.missed_dose, "",
            "une fiche vidée exprès a été resemée"
        );

        let _ = std::fs::remove_file(&path);
    }

    /// A conduite rule that matches no card is content nobody will
    /// ever read: every key must reach at least one starter fiche.
    /// Every shipped card either gets the two counter answers, or is on
    /// the short list of products a professional administers.
    ///
    /// « En cas d'oubli » means nothing for a perfusion, an intravitreal
    /// injection or an oxytocic, so those are deliberately left blank —
    /// the same discipline as the specialist-titrated classes that ship
    /// without a posology. What this test forbids is the third case: a
    /// card that falls through the rules by accident and nobody notices,
    /// because a blank section looks exactly like a deliberate one.
    #[test]
    fn every_card_has_the_two_answers_or_is_a_named_exception() {
        // Given by someone else — a perfusion, an injection in a care
        // setting, an emergency kit a bystander uses. There is no dose
        // to forget, and inventing one would be worse than the blank.
        const ADMINISTERED: &[&str] = &[
            "Arixtra",
            "Arganova",
            "Meronem",
            "Vancomycine",
            "Xolair",
            "Eylea",
            "Lucentis",
            "Avastin",
            "Herceptin",
            "Navelbine",
            "Velcade",
            "Kisqali",
            "Votrient",
            "Orencia",
            "Entyvio",
            "MisoOne",
            "Gonal-f",
            "Syntocinon",
            "Tractocile",
            "Cyanokit",
            "Qutenza",
            "Xylocaïne",
            "Naropéine",
            "Marcaïne",
            "Chirocaïne",
            "Scandicaïne",
            "Nalador",
            "Méthergin",
            "Rhophylac",
            "Beyfortus",
            "GlucaGen",
            "Prenoxad",
        ];
        // Taken by the patient and still without the two answers. The
        // list is empty as of v0.84.0, and the assertion below keeps it
        // that way: a card added tomorrow without its two sections
        // fails here rather than reaching a counter with a blank that
        // looks deliberate. Anything parked here is a debt, not a
        // decision — unlike ADMINISTERED above, which is a decision.
        const PENDING: &[&str] = &[];
        // The same match the seeding pass uses: class, tags, DCI, name.
        let tags = |name: &str| {
            STARTER_DETAILS
                .iter()
                .find(|d| d.name == name)
                .map(|d| d.tags)
                .unwrap_or("")
        };
        let uncovered: Vec<&str> = STARTER_DRUGS
            .iter()
            .filter(|(name, dci, class, _)| {
                !STARTER_CONDUITE.iter().any(|(key, _, _)| {
                    class.contains(key)
                        || tags(name).contains(key)
                        || dci.contains(key)
                        || name.contains(key)
                })
            })
            .map(|(name, ..)| *name)
            .collect();
        let unexpected: Vec<&&str> = uncovered
            .iter()
            .filter(|n| !ADMINISTERED.contains(n) && !PENDING.contains(n))
            .collect();
        assert!(
            unexpected.is_empty(),
            "fiches sans « en cas d'oubli » ni « ce qui doit faire consulter », \
             et qui ne sont pas administrées par un professionnel :\n{unexpected:#?}"
        );
        // …and the exception list stays honest: an entry that a rule has
        // since caught is an entry to delete, not to keep as an alibi.
        let stale: Vec<&&str> = ADMINISTERED
            .iter()
            .chain(PENDING.iter())
            .filter(|n| !uncovered.contains(n))
            .collect();
        assert!(
            stale.is_empty(),
            "exceptions devenues inutiles — une règle les atteint, \
             il faut les retirer de la liste : {stale:?}"
        );
    }

    /// The posology coverage only ever improves.
    ///
    /// Some classes will never carry a counter posology: the dose of an
    /// antiepileptic, an antipsychotic or an oral anticancer is titrated
    /// by the specialist against the patient, and a plausible-looking
    /// line there would be worse than a blank one. A vaccine's schedule
    /// lives in [`crate::vaccines`]. Those are named below and stay
    /// named.
    ///
    /// The rest is honest debt: 813 cards, and a good third still
    /// without their line — collyres, laxatifs, insulines, pénicillines,
    /// contraceptions. Rather than invent an exception list that would
    /// launder that debt into a decision, this test is a ratchet: it
    /// records how many classes are still uncovered and fails if the
    /// number grows. Adding a card without a posology in a new class is
    /// caught; every batch written lowers the figure, and lowering it is
    /// the point.
    #[test]
    fn the_posology_coverage_only_improves() {
        // Titrated by the specialist, or scheduled elsewhere: no
        // counter posology exists to write.
        const NO_POSOLOGY: &[&str] = &[
            "antiépileptique",
            "antipsychotique",
            "immunosuppresseur",
            "inhibiteur JAK",
            "immunomodulateur — SEP",
            "anticorps monoclonal — SEP",
            "modulateur S1P — SEP",
            "anti-CD20",
            "anticancéreux oral",
            "alkylant",
            "anti-HER2",
            "anti-VEGF",
            "anti-estrogène",
            "hormonothérapie — anti-aromatase",
            "analogue de la GnRH",
            "antagoniste de la GnRH",
            "inhibiteur CDK4/6",
            "inhibiteur du protéasome",
            "inhibiteur de tyrosine kinase",
            "immunothérapie anti-PD-1",
            "alcaloïde de la pervenche",
            "vaccin",
        ];
        // Lower this as batches are written. It may never rise.
        //
        // At 34 the remainder is no longer a debt of writing: what is
        // left is injected or perfused by someone else — anesthésiques
        // locaux injectables, aminosides, carbapénèmes, glycopeptides,
        // biologiques intraveineux, gonadotrophines de FIV, produits de
        // l'urgence obstétricale, toxine botulique. There is no counter
        // posology to write for them, and inventing one would be worse
        // than the blank. They are deliberately *not* added to
        // `NO_POSOLOGY`: an exemption list would whitewash the debt,
        // and the point of this ratchet is that it stays visible.
        const CEILING: usize = 34;

        let with: std::collections::HashSet<&str> = STARTER_POSOLOGIES
            .iter()
            .map(|(brand, ..)| *brand)
            .collect();
        let mut classes: Vec<&str> = STARTER_DRUGS
            .iter()
            .filter(|(name, ..)| !with.contains(name))
            .filter(|(_, _, class, _)| !NO_POSOLOGY.iter().any(|c| class.contains(c)))
            .map(|(_, _, class, _)| *class)
            .collect();
        classes.sort_unstable();
        classes.dedup();
        assert!(
            classes.len() <= CEILING,
            "{} classes sans posologie, le plafond est {CEILING} : \
             une fiche a été ajoutée sans sa ligne, ou une classe a été \
             retirée de la liste des exemptions",
            classes.len()
        );
        // The ceiling is not allowed to drift far above reality either:
        // a plafond that nobody lowers stops being a ratchet.
        assert!(
            classes.len() + 25 >= CEILING,
            "le plafond {CEILING} est loin devant les {} classes restantes — abaissez-le",
            classes.len()
        );
    }

    #[test]
    fn every_conduite_rule_reaches_a_card() {
        for (key, _, _) in STARTER_CONDUITE {
            let reached = STARTER_DRUGS.iter().any(|(name, dci, class, _)| {
                class.contains(key) || dci.contains(key) || name.contains(key)
            });
            assert!(reached, "règle de conduite orpheline : {key}");
        }
    }

    /// Every shipped formula must be readable by the codex: a line the
    /// parser cannot scale is a line the counter has to compute by
    /// hand, which is what the codex exists to avoid.
    #[test]
    fn every_shipped_formula_scales() {
        // The codex only ever grows: a preparation removed is a formula
        // the préparatoire has to go and find in a book.
        assert!(
            STARTER_PREPARATIONS.len() >= 52,
            "{} préparations livrées, il y en avait cinquante-deux",
            STARTER_PREPARATIONS.len()
        );
        let mut names = std::collections::HashSet::new();
        for p in STARTER_PREPARATIONS {
            assert!(
                names.insert(p.name),
                "deux préparations portent le même nom : {}",
                p.name
            );
            let lines = crate::codex::parse_formula(p.formula);
            assert!(!lines.is_empty(), "{} : formule vide", p.name);
            // The yield is what a target quantity is compared against.
            assert!(
                crate::codex::parse_amount(p.yield_amount).is_some(),
                "{} : rendement illisible ({})",
                p.name,
                p.yield_amount
            );
            // At least one ingredient carries a quantity that scales.
            // A « formule type » is the exception: its quantities come
            // from the prescription, and it says so in its name.
            let template = p.name.contains("formule type");
            assert!(
                template || lines.iter().any(|l| l.quantity.is_some()),
                "{} : aucune quantité chiffrée",
                p.name
            );
            // And the whole thing must scale without losing a line.
            let factor = crate::codex::scale_factor(p.yield_amount, "60 g")
                .or_else(|| crate::codex::scale_factor(p.yield_amount, "500 mL"))
                .or_else(|| crate::codex::scale_factor(p.yield_amount, "10 gélules"))
                .unwrap_or(1.0);
            for line in &lines {
                assert!(
                    !line.scaled(factor).trim().is_empty(),
                    "{} : ligne « {} » vide une fois mise à l'échelle",
                    p.name,
                    line.name
                );
            }
        }
    }

    /// A base written by an older version must open, and come back with
    /// every column the current code selects. The migrations are what
    /// make that true, and they are only true if they are run.
    #[test]
    fn a_base_from_an_older_version_still_opens() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-old-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("old.db");
        let _ = std::fs::remove_file(&path);
        // The schema as it was several versions ago: no operator on an
        // act, no missed_dose on a card, no biology, no codex.
        {
            let conn = Connection::open(&path).unwrap();
            conn.pragma_update(None, "key", "secret").unwrap();
            conn.execute_batch(
                "CREATE TABLE patients (
                     id INTEGER PRIMARY KEY, last_name TEXT NOT NULL,
                     first_name TEXT NOT NULL, birth_date TEXT NOT NULL
                 );
                 CREATE TABLE interviews (
                     id INTEGER PRIMARY KEY,
                     patient_id INTEGER NOT NULL REFERENCES patients(id),
                     kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'IDENTIFIED',
                     created_at TEXT NOT NULL DEFAULT (datetime('now')),
                     updated_at TEXT NOT NULL DEFAULT (datetime('now'))
                 );
                 -- The drug card as the first version wrote it: no
                 -- DCI, no class, no monograph.
                 CREATE TABLE drugs (
                     id INTEGER PRIMARY KEY, name TEXT NOT NULL,
                     dosage TEXT NOT NULL DEFAULT '', ddi TEXT NOT NULL DEFAULT '',
                     iup TEXT NOT NULL DEFAULT '', antidote TEXT NOT NULL DEFAULT '',
                     notes TEXT NOT NULL DEFAULT ''
                 );
                 INSERT INTO patients (last_name, first_name, birth_date)
                 VALUES ('Dupont', 'Jean', '1958-07-03');
                 INSERT INTO interviews (patient_id, kind) VALUES (1, 'BPM');
                 INSERT INTO drugs (name, dosage) VALUES ('Eliquis', '5 mg x2/j');",
            )
            .unwrap();
        }
        // Opening it runs the migrations; everything the code reads must
        // now be there.
        let db = Db::open(&path, "secret").unwrap();
        let patients = db.patients().unwrap();
        assert_eq!(patients.len(), 1);
        let acts = db.interviews_for(patients[0].id).unwrap();
        assert_eq!(acts.len(), 1);
        assert_eq!(acts[0].operator, "");
        let drugs = db.drugs().unwrap();
        assert_eq!(drugs.len(), 1);
        // The columns of the first version are still there…
        assert_eq!(drugs[0].dosage, "5 mg x2/j");
        // …and every one added since has been migrated in.
        assert_eq!(drugs[0].missed_dose, "");
        assert_eq!(drugs[0].class, "");
        assert_eq!(drugs[0].indications, "");
        // The tables that did not exist at all are created, and usable.
        assert!(db.bio_results(patients[0].id).unwrap().is_empty());
        assert!(db.preparations().unwrap().is_empty());
        assert!(db.watchlist().unwrap().is_empty());
        // And the content that seeds onto an existing base does seed.
        assert!(db.seed_preparations().unwrap() > 0);
        assert!(db.seed_protocols().unwrap() > 0);
        // The conduite rules match on the class, which this old card
        // does not have: nothing to fill, and nothing broken either.
        assert_eq!(db.seed_conduite().unwrap(), 0);

        let _ = std::fs::remove_file(&path);
    }

    /// The protocols ship with content: the tool was a beautiful empty
    /// tree until it did.
    #[test]
    fn the_protocols_seed_once_and_keep_their_shape() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-proto-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("proto.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        assert_eq!(db.seed_protocols().unwrap(), STARTER_PROTOCOLS.len());
        assert_eq!(db.seed_protocols().unwrap(), 0);
        let protocols = db.protocols().unwrap();
        assert_eq!(protocols.len(), STARTER_PROTOCOLS.len());
        for p in &protocols {
            let nodes = db.protocol_nodes(p.id).unwrap();
            assert!(nodes.len() >= 3, "{} : arbre trop court", p.title);
            // Exactly one root, and every other node hangs from a
            // question by one of its two branches.
            let roots: Vec<&ProtocolNode> =
                nodes.iter().filter(|n| n.parent_id.is_none()).collect();
            assert_eq!(roots.len(), 1, "{} : plusieurs racines", p.title);
            for node in nodes.iter().filter(|n| n.parent_id.is_some()) {
                assert_ne!(
                    node.branch,
                    Branch::Root,
                    "{} : branche sans réponse",
                    p.title
                );
                let parent = nodes
                    .iter()
                    .find(|n| Some(n.id) == node.parent_id)
                    .expect("le parent existe");
                assert_eq!(
                    parent.kind,
                    NodeKind::Question,
                    "{} : une conduite ne se ramifie pas",
                    p.title
                );
            }
            // Every question has both of its answers: a walk-through
            // that dead-ends on « non » is worse than no protocol.
            for question in nodes.iter().filter(|n| n.kind == NodeKind::Question) {
                for branch in [Branch::Yes, Branch::No] {
                    assert!(
                        nodes
                            .iter()
                            .any(|n| n.parent_id == Some(question.id) && n.branch == branch),
                        "{} : « {} » sans branche {:?}",
                        p.title,
                        question.text,
                        branch
                    );
                }
            }
        }
        // A tree the team rewrote is never replaced.
        let first = protocols[0].id;
        let nodes = db.protocol_nodes(first).unwrap();
        assert!(db
            .update_protocol_node(
                nodes[0].id,
                nodes[0].kind,
                "La question de l'officine.",
                &nodes[0].text,
            )
            .unwrap());
        db.seed_protocols().unwrap();
        assert_eq!(
            db.protocol_nodes(first).unwrap()[0].text,
            "La question de l'officine."
        );

        let _ = std::fs::remove_file(&path);
    }

    /// A protocol is a walk-through, not a leaflet: it earns its place
    /// by asking something the counter would not have asked, and by
    /// ending on a conduite precise enough to act on. One question and
    /// two slogans is a card, and belongs on a fiche.
    #[test]
    fn every_protocol_asks_before_it_answers() {
        // The catalogue only ever grows: a protocol removed is a
        // question nobody asks any more.
        assert!(
            STARTER_PROTOCOLS.len() >= 36,
            "{} protocoles livrés, il y en avait trente-six",
            STARTER_PROTOCOLS.len()
        );

        fn walk(nodes: &[StarterNode], questions: &mut usize, actions: &mut Vec<&'static str>) {
            for node in nodes {
                assert!(!node.text.trim().is_empty());
                match node.kind {
                    NodeKind::Question => {
                        *questions += 1;
                        assert!(
                            node.text.trim_end().ends_with('?'),
                            "une question qui ne se termine pas par un point d'interrogation : {}",
                            node.text
                        );
                        walk(node.yes, questions, actions);
                        walk(node.no, questions, actions);
                    }
                    NodeKind::Action => actions.push(node.text),
                }
            }
        }

        let mut titles: Vec<&str> = STARTER_PROTOCOLS.iter().map(|p| p.title).collect();
        titles.sort_unstable();
        let seen = titles.len();
        titles.dedup();
        assert_eq!(seen, titles.len(), "deux protocoles portent le même titre");

        for p in STARTER_PROTOCOLS {
            assert!(!p.subject.trim().is_empty(), "{} : sans sujet", p.title);
            let (mut questions, mut actions) = (0, Vec::new());
            walk(p.steps, &mut questions, &mut actions);
            assert!(
                questions >= 2,
                "{} : une seule question, ce n'est pas un arbre",
                p.title
            );
            assert!(
                actions.len() >= 3,
                "{} : {} conduites seulement",
                p.title,
                actions.len()
            );
            for conduite in &actions {
                // What to do, not what is wrong: a conduite short
                // enough to fit on a button says nothing.
                assert!(
                    conduite.chars().count() >= 80,
                    "{} : conduite trop courte pour être suivie — « {conduite} »",
                    p.title
                );
            }
        }
    }

    /// The codex seeds once and then belongs to the team: a rewritten
    /// formula survives the next launch, and every shipped preparation
    /// carries what the counter needs to make it.
    #[test]
    fn the_codex_seeds_once_and_stays_the_team_s() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-codex-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("codex.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let seeded = db.seed_preparations().unwrap();
        assert_eq!(seeded, STARTER_PREPARATIONS.len());
        // A second pass adds nothing.
        assert_eq!(db.seed_preparations().unwrap(), 0);
        let all = db.preparations().unwrap();
        assert_eq!(all.len(), STARTER_PREPARATIONS.len());
        // Every shipped preparation says what it is for, what goes into
        // it, what it yields, what goes wrong and where it comes from.
        for p in &all {
            assert!(
                !p.indication.trim().is_empty(),
                "{} sans indication",
                p.name
            );
            assert!(!p.formula.trim().is_empty(), "{} sans formule", p.name);
            assert!(
                !p.yield_amount.trim().is_empty(),
                "{} sans rendement",
                p.name
            );
            assert!(
                !p.method.trim().is_empty(),
                "{} sans mode opératoire",
                p.name
            );
            assert!(
                !p.caution.trim().is_empty(),
                "{} sans mise en garde",
                p.name
            );
            assert!(
                !p.conservation.trim().is_empty(),
                "{} sans conservation",
                p.name
            );
            assert!(!p.sources.trim().is_empty(), "{} sans source", p.name);
            // A formula line is « nom | quantité ».
            for line in p.formula.lines().filter(|l| !l.trim().is_empty()) {
                assert!(
                    line.contains('|'),
                    "{} : ligne de formule sans quantité — {line}",
                    p.name
                );
            }
        }
        // The team rewrites one, and the next launch leaves it alone.
        let mut edited = all[0].clone();
        let base = edited.clone();
        edited.formula = "Acide salicylique | 3 g\nVaseline blanche | qsp 100 g".to_owned();
        assert!(db.update_preparation(&edited, &base).unwrap());
        // A second write from the stale view is refused.
        assert!(!db.update_preparation(&edited, &base).unwrap());
        assert_eq!(db.seed_preparations().unwrap(), 0);
        assert_eq!(db.preparations().unwrap()[0].formula, edited.formula);
        // And one added by hand behaves like any other.
        let id = db.add_preparation("Pommade de l'officine").unwrap();
        assert!(db.preparations().unwrap().iter().any(|p| p.id == id));
        assert!(!db.delete_preparation(id, "Autre nom").unwrap());
        assert!(db.delete_preparation(id, "Pommade de l'officine").unwrap());

        let _ = std::fs::remove_file(&path);
    }

    /// The dispositifs follow the codex's discipline: seeded once, the
    /// team's afterwards. And every shipped fiche must answer the six
    /// questions the counter actually asks — a fiche that only names
    /// the box is a fiche nobody opens twice.
    #[test]
    fn the_dispositifs_seed_once_and_answer_the_counter() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-dispo-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("dispo.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        // The catalogue only ever grows: a fiche removed is a question
        // the counter can no longer answer from the application.
        assert!(
            STARTER_DISPOSITIFS.len() >= 47,
            "{} dispositifs livrés, il y en avait quarante-sept",
            STARTER_DISPOSITIFS.len()
        );
        assert_eq!(
            db.seed_dispositifs().unwrap(),
            STARTER_DISPOSITIFS.len(),
            "le premier semis pose toutes les fiches"
        );
        assert_eq!(db.seed_dispositifs().unwrap(), 0, "le second n'ajoute rien");
        let all = db.dispositifs().unwrap();
        assert_eq!(all.len(), STARTER_DISPOSITIFS.len());
        // Names are unique, or the seed would skip one silently.
        let mut names: Vec<&str> = all.iter().map(|d| d.name.as_str()).collect();
        names.sort_unstable();
        let seen = names.len();
        names.dedup();
        assert_eq!(seen, names.len(), "deux dispositifs portent le même nom");
        for d in &all {
            for (label, body) in [
                ("famille", &d.family),
                ("indication", &d.indication),
                ("formes et tailles", &d.sizes),
                ("pose", &d.application),
                ("renouvellement", &d.renewal),
                ("prise en charge", &d.lpp),
                ("mise en garde", &d.caution),
                ("étiquettes", &d.tags),
                ("sources", &d.sources),
            ] {
                assert!(!body.trim().is_empty(), "{} : sans {label}", d.name);
            }
            // The LPP field carries the rule, never a price: a tarif
            // shipped in a fiche is a tarif wrong within the year.
            assert!(
                !d.lpp.contains('€'),
                "{} : un tarif dans la ligne LPP — la fiche donne la règle, pas le prix",
                d.name
            );
        }
        // The families are a short, shared vocabulary: the list groups
        // on them, so a family invented once sits alone forever.
        const FAMILIES: &[&str] = &[
            "Pansement",
            "Fixation",
            "Compression",
            "Stomie",
            "Sondage urinaire",
            "Incontinence",
            "Set de soins",
            "Injection",
            "Diabète",
            "Respiratoire",
            "Location",
        ];
        for d in &all {
            assert!(
                FAMILIES.contains(&d.family.as_str()),
                "{} : famille « {} » hors du vocabulaire",
                d.name,
                d.family
            );
        }
        // Every family is actually used: a name in that list with no
        // fiche behind it is a heading that never prints.
        for family in FAMILIES {
            assert!(
                all.iter().any(|d| d.family == *family),
                "famille sans fiche : {family}"
            );
        }
        // The rented material is what the roadmap asked for by name.
        for machine in ["Nébuliseur", "Neurostimulateur", "Lit médicalisé"] {
            assert!(
                all.iter().any(|d| d.name.contains(machine)),
                "aucune fiche pour {machine}"
            );
        }
        // The team rewrites one, and the next launch leaves it alone.
        let mut edited = all[0].clone();
        let base = edited.clone();
        edited.renewal = "Tous les jours, ici.".to_owned();
        assert!(db.update_dispositif(&edited, &base).unwrap());
        // A second write from the stale view is refused.
        assert!(!db.update_dispositif(&edited, &base).unwrap());
        assert_eq!(db.seed_dispositifs().unwrap(), 0);
        assert_eq!(db.dispositifs().unwrap()[0].renewal, edited.renewal);
        // One added by hand behaves like any other, deletion included.
        let id = db.add_dispositif("Attelle de l'officine").unwrap();
        assert!(db.dispositifs().unwrap().iter().any(|d| d.id == id));
        assert!(!db.delete_dispositif(id, "Autre nom").unwrap());
        assert!(db.delete_dispositif(id, "Attelle de l'officine").unwrap());
        // A base emptied on purpose stays empty: the seed mark says the
        // pass has run here, so the fiches do not come back to argue.
        for d in db.dispositifs().unwrap() {
            assert!(db.delete_dispositif(d.id, &d.name).unwrap());
        }
        assert_eq!(db.seed_dispositifs().unwrap(), 0);
        assert!(db.dispositifs().unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    /// A rental is a shared row like any other: two posts must not both
    /// believe they took the same machine back.
    #[test]
    fn a_rental_runs_until_it_is_taken_back() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-loc-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("loc.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Lefèvre", "Hélène", "1948-02-11").unwrap();
        let row = Location {
            id: 0,
            patient_id: pid,
            label: "Nébuliseur".to_owned(),
            lpp: "Aérosolthérapie — titre I".to_owned(),
            period: "semaine".to_owned(),
            fee: 12.0,
            renewal_days: 28,
            max_periods: 0,
            started_on: "2026-03-03".to_owned(),
            ended_on: String::new(),
            renewed_on: String::new(),
            remark: String::new(),
        };
        let id = db.add_location(&row).unwrap();
        let all = db.locations_for(pid).unwrap();
        assert_eq!(all.len(), 1);
        let l = &all[0];
        assert!(l.running(), "une location sans reprise est en cours");
        assert_eq!(l.period(), crate::config::Period::Week);
        // The renewal counts from the day it went out until one is
        // recorded, and from that day afterwards.
        assert_eq!(l.renewal_base(), "2026-03-03");
        // It is on the running list, with the patient's name beside it.
        let running = db.running_locations().unwrap();
        assert_eq!(running.len(), 1);
        assert!(running[0].1.contains("Hélène"));
        // A renewal moves the base without touching the rest.
        assert!(db
            .update_location_dates(id, &l.started_on, "", "2026-03-30", ("2026-03-03", "", ""))
            .unwrap());
        let l = db.locations_for(pid).unwrap().remove(0);
        assert_eq!(l.renewal_base(), "2026-03-30");
        assert!(l.running());
        // A second post still showing the old dates is refused rather
        // than closing a rental someone else already renewed.
        assert!(!db
            .update_location_dates(id, "2026-03-03", "2026-04-10", "", ("2026-03-03", "", ""))
            .unwrap());
        // With the values actually on screen, the return goes through.
        assert!(db
            .update_location_dates(
                id,
                &l.started_on,
                "2026-04-10",
                &l.renewed_on,
                (&l.started_on, "", "2026-03-30")
            )
            .unwrap());
        let l = db.locations_for(pid).unwrap().remove(0);
        assert!(!l.running());
        assert_eq!(l.ended_on, "2026-04-10");
        // And it drops off the running list.
        assert!(db.running_locations().unwrap().is_empty());
        // Deletion is compare-and-set on the label displayed.
        assert!(!db.delete_location(id, "Autre matériel").unwrap());
        assert!(db.delete_location(id, "Nébuliseur").unwrap());
        assert!(db.locations_for(pid).unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    /// A new act carries the counter's day, not the UTC one. Between
    /// 22 h and minuit UTC — after midnight in France — the two differ,
    /// and a pharmacie de garde works then.
    #[test]
    fn a_new_act_is_stamped_in_the_counter_s_own_day() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-clock-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("clock.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        db.add_interview(pid, InterviewKind::Bpm).unwrap();
        let today = db.today_iso().unwrap();
        let act = &db.interviews_for(pid).unwrap()[0];
        assert_eq!(
            &act.created_at[..10],
            today,
            "l'acte doit porter le jour du comptoir"
        );
        // And so does the file itself.
        let created: String = db
            .conn
            .query_row(
                "SELECT substr(created_at, 1, 10) FROM patients WHERE id = ?1",
                [pid],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(created, today);

        let _ = std::fs::remove_file(&path);
    }

    /// Moving an act to the day it was held is not cosmetic: the date
    /// places it in its cycle, and the cycle picks the fee. This is the
    /// billing consequence, checked end to end.
    #[test]
    fn moving_an_act_moves_its_year_and_its_rank() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-move-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("move.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let first = db.add_interview(pid, InterviewKind::Bpm).unwrap();
        let second = db.add_interview(pid, InterviewKind::Bpm).unwrap();
        let today = db.today_iso().unwrap();
        // Both created today: same year, ranks 0 and 1.
        let ranks: Vec<(usize, usize)> = db
            .export_rows(12)
            .unwrap()
            .iter()
            .map(|r| (r.fee_year, r.fee_rank))
            .collect();
        assert_eq!(ranks, vec![(0, 0), (0, 1)]);
        // The first one actually happened two years ago: it opens its
        // own cycle, and the one left today becomes the first of the
        // current year.
        assert!(db.set_created_date(first, "2024-03-02", &today).unwrap());
        let rows = db.export_rows(12).unwrap();
        let moved = rows
            .iter()
            .find(|r| r.created_date == "2024-03-02")
            .expect("l'acte déplacé est là");
        let stayed = rows
            .iter()
            .find(|r| r.created_date == today)
            .expect("l'autre aussi");
        assert_eq!((moved.fee_year, moved.fee_rank), (0, 0));
        // Two years later, the second act opens the next année
        // d'accompagnement — and is its first entretien, not its second.
        assert_eq!(stayed.fee_rank, 0);
        assert!(
            stayed.fee_year >= 1,
            "année {} attendue ≥ 1",
            stayed.fee_year
        );
        let _ = second;

        let _ = std::fs::remove_file(&path);
    }

    /// An act carries who did it, so the fiche and the courrier are
    /// signed by that person and not by whoever prints them.
    #[test]
    fn an_act_records_who_did_it() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-actby-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("actby.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let id = db
            .add_interview_by(pid, InterviewKind::Bpm, "Observance", " CL ")
            .unwrap();
        // Trimmed on the way in: " CL " and "CL" are the same person.
        assert_eq!(db.interviews_for(pid).unwrap()[0].operator, "CL");
        // A write from a stale view is rejected, not applied.
        assert!(!db.set_interview_operator(id, "MB", "YS").unwrap());
        assert!(db.set_interview_operator(id, "YS", "CL").unwrap());
        assert_eq!(db.interviews_for(pid).unwrap()[0].operator, "YS");
        // And it reaches the export, where the billing is reconciled.
        assert_eq!(db.export_rows(12).unwrap()[0].operator, "YS");

        let _ = std::fs::remove_file(&path);
    }

    /// The act entered the morning after must be datable to the day it
    /// was held: that date is what places it in its cycle, and the
    /// cycle is what picks the fee.
    #[test]
    fn an_act_can_be_moved_to_the_day_it_was_held() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-actdate-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("actdate.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        let pid = db.add_patient("Dupont", "Jean", "1958-07-03").unwrap();
        let id = db.add_interview(pid, InterviewKind::Bpm).unwrap();
        let today = db.interviews_for(pid).unwrap()[0].created_at[..10].to_owned();
        let clock = db.interviews_for(pid).unwrap()[0].created_at[10..].to_owned();
        // A write from a stale view is rejected, not applied.
        assert!(!db.set_created_date(id, "2026-03-02", "1999-01-01").unwrap());
        assert_eq!(db.interviews_for(pid).unwrap()[0].created_at[..10], today);
        assert!(db.set_created_date(id, "2026-03-02", &today).unwrap());
        let moved = db.interviews_for(pid).unwrap()[0].created_at.clone();
        assert_eq!(&moved[..10], "2026-03-02");
        // Only the day moved: the clock time still orders two acts of
        // the same day.
        assert_eq!(&moved[10..], clock);
        // And the act is now read at its new date everywhere.
        assert_eq!(
            db.interview_dates_for(pid, InterviewKind::Bpm).unwrap(),
            vec!["2026-03-02".to_owned()]
        );
        assert_eq!(db.export_rows(12).unwrap()[0].created_date, "2026-03-02");

        let _ = std::fs::remove_file(&path);
    }

    /// The « toxicité » sections say something drug-specific, and the
    /// one-time replacement of the old boilerplate never touches a cell
    /// the team has written on.
    #[test]
    fn the_toxicity_sections_say_what_is_toxic_and_at_what_dose() {
        const OLD: &str = "Marge thérapeutique étroite : un écart de dose ou une interaction suffit à faire basculer vers le sous-dosage ou la toxicité. Voir les sections Interactions et Surveillance.";
        // No card is left with the sentence that sent the reader to
        // another section. A field that answers nothing is worse than
        // an empty one: the empty one at least looks unfinished.
        for d in STARTER_DETAILS {
            assert_ne!(d.toxicity, OLD, "{} garde l'ancien texte", d.name);
            if !d.toxicity.is_empty() {
                assert!(
                    d.toxicity.len() > 150,
                    "« toxicité » de {} trop courte pour dire une marge",
                    d.name
                );
            }
        }
        // The four AOD carry one: they are the app's own subject, and
        // their margin is not a concentration but a set of criteria.
        for name in ["Eliquis", "Xarelto", "Pradaxa", "Lixiana"] {
            let card = STARTER_DETAILS
                .iter()
                .find(|d| d.name == name)
                .unwrap_or_else(|| panic!("fiche {name} absente"));
            assert!(!card.toxicity.is_empty(), "{name} sans section toxicité");
        }

        let dir = std::env::temp_dir().join(format!("bpm-caddy-tox-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("tox.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        db.seed_drugs_if_empty().unwrap();

        // An old base: two cards still carrying the boilerplate, one of
        // which the team has since rewritten in its own words.
        for name in ["Digoxine", "Levothyrox"] {
            db.conn
                .execute(
                    "UPDATE drugs SET toxicity = ?1 WHERE name = ?2",
                    (OLD, name),
                )
                .unwrap();
        }
        db.conn
            .execute(
                "UPDATE drugs SET toxicity = 'Notre protocole interne.' WHERE name = 'Téralithe'",
                (),
            )
            .unwrap();
        let read = |name: &str| {
            db.drugs()
                .unwrap()
                .into_iter()
                .find(|d| d.name == name)
                .unwrap()
                .toxicity
        };

        // Two boilerplate cells replaced, plus every card whose section
        // was empty and unlocked — the pass carries the whole set.
        let changed = db.refresh_toxicity().unwrap();
        assert!(changed >= 2, "la passe n'a rien porté : {changed}");
        assert!(read("Digoxine").contains("0,5 à 0,9 ng/mL"));
        assert!(read("Levothyrox").contains("TSH"));
        // What the team wrote is theirs, boilerplate or not.
        assert_eq!(read("Téralithe"), "Notre protocole interne.");
        // And the pass runs once: a second launch costs one query.
        assert_eq!(db.refresh_toxicity().unwrap(), 0);
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn posologies_seed_once_and_stay_the_team_s() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-poso-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("poso.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        db.seed_drugs_if_empty().unwrap();

        // Every shipped line names a drug of the base, and the seed put
        // them in order on the right card.
        let eliquis = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name == "Eliquis")
            .unwrap();
        let rows = db.posologies(eliquis.id).unwrap();
        assert!(!rows.is_empty());
        let shipped: Vec<&str> = STARTER_POSOLOGIES
            .iter()
            .filter(|(brand, ..)| *brand == "Eliquis")
            .map(|(_, indication, ..)| *indication)
            .collect();
        assert_eq!(
            rows.iter()
                .map(|r| r.indication.as_str())
                .collect::<Vec<_>>(),
            shipped
        );

        // A card the team has written on is never re-seeded.
        let first = rows[0].clone();
        assert!(db.delete_posologie(first.id, &first.indication).unwrap());
        assert_eq!(db.seed_posologies().unwrap(), 0);
        assert_eq!(db.posologies(eliquis.id).unwrap().len(), rows.len() - 1);

        // Editing is compare-and-set on the indication displayed.
        let mut edited = db.posologies(eliquis.id).unwrap()[0].clone();
        let expected = edited.indication.clone();
        edited.posologie = "Protocole interne".to_owned();
        assert!(!db
            .update_posologie(edited.id, &edited, "autre chose")
            .unwrap());
        assert!(db.update_posologie(edited.id, &edited, &expected).unwrap());
        assert_eq!(
            db.posologies(eliquis.id).unwrap()[0].posologie,
            "Protocole interne"
        );

        // Deleting the card takes its posologies with it.
        assert!(db.delete_drug(eliquis.id, "Eliquis").unwrap());
        assert!(db.posologies(eliquis.id).unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn class_notes_are_shared_and_clearable() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-class-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("class.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        assert_eq!(db.class_note("AOD").unwrap(), "");
        assert!(db
            .set_class_note("AOD", "  Toujours vérifier la clairance.  ", "")
            .unwrap());
        // Stored trimmed, found whatever the case of the class.
        assert_eq!(
            db.class_note("AOD").unwrap(),
            "Toujours vérifier la clairance."
        );
        assert_eq!(
            db.class_note("aod").unwrap(),
            "Toujours vérifier la clairance."
        );
        // The same class written in another case is the same note, and
        // a write from a stale view is refused.
        assert!(db
            .set_class_note(
                "aod",
                "Écrit depuis l'autre casse.",
                "Toujours vérifier la clairance."
            )
            .unwrap());
        assert_eq!(db.class_note("AOD").unwrap(), "Écrit depuis l'autre casse.");
        assert!(!db.set_class_note("AOD", "Perdu", "texte d'hier").unwrap());
        assert_eq!(db.class_note("AOD").unwrap(), "Écrit depuis l'autre casse.");
        // An empty body clears the note rather than storing a blank.
        assert!(db
            .set_class_note("AOD", "   ", "Écrit depuis l'autre casse.")
            .unwrap());
        assert_eq!(db.class_note("AOD").unwrap(), "");
        // A card with no class is a no-op, never an error.
        assert!(db.set_class_note("", "rien", "").unwrap());
        assert_eq!(db.class_note("").unwrap(), "");

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn table_cells_override_and_reset() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-cells-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("cells.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        assert!(db
            .set_table_cell("IPP", 0, 1, "25 mg", "20 mg", "20 mg")
            .unwrap());
        assert_eq!(
            db.table_cells("IPP").unwrap().get(&(0, 1)).unwrap(),
            "25 mg"
        );
        // A correction written over a colleague's newer one is refused.
        assert!(!db
            .set_table_cell("IPP", 0, 1, "30 mg", "20 mg", "20 mg")
            .unwrap());
        assert_eq!(
            db.table_cells("IPP").unwrap().get(&(0, 1)).unwrap(),
            "25 mg"
        );
        // Writing the shipped value back drops the override entirely.
        assert!(db
            .set_table_cell("IPP", 0, 1, "20 mg", "20 mg", "25 mg")
            .unwrap());
        assert!(db.table_cells("IPP").unwrap().is_empty());
        db.set_table_cell("IPP", 0, 1, "25 mg", "20 mg", "20 mg")
            .unwrap();
        db.set_table_cell("IPP", 1, 2, "15 mg", "20 mg", "20 mg")
            .unwrap();
        assert_eq!(db.all_table_cells().unwrap().len(), 2);
        assert_eq!(db.reset_table("IPP").unwrap(), 2);
        assert!(db.all_table_cells().unwrap().is_empty());

        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn starter_details_fill_only_empty_fields() {
        let dir = std::env::temp_dir().join(format!("bpm-caddy-detail-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("detail.db");
        let _ = std::fs::remove_file(&path);
        let db = Db::open(&path, "secret").unwrap();
        db.seed_drugs_if_empty().unwrap();

        // Every detailed card names a drug of the starter list, and the
        // seed applied its clinical fields.
        let drugs = db.drugs().unwrap();
        for d in STARTER_DETAILS {
            let card = drugs
                .iter()
                .find(|x| x.name == d.name)
                .unwrap_or_else(|| panic!("fiche « {} » absente de la base", d.name));
            assert_eq!(card.dosage, d.dosage);
            assert_eq!(card.iup, d.iup);
        }

        // The team's own text is never overwritten by a later top-up,
        // and a field they cleared stays theirs to refill.
        let base = drugs.iter().find(|d| d.name == "Eliquis").unwrap().clone();
        let mut edited = base.clone();
        edited.dosage = "Protocole interne : 5 mg x2/j, revoir à 3 mois".to_owned();
        edited.ddi = String::new();
        assert!(db.update_drug(&edited, &base).unwrap());
        db.fill_starter_details().unwrap();
        let after = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name == "Eliquis")
            .unwrap();
        assert_eq!(
            after.dosage,
            "Protocole interne : 5 mg x2/j, revoir à 3 mois"
        );
        // A field the team emptied on purpose stays empty: the
        // top-up must never argue with what they decided.
        assert!(after.ddi.is_empty());
        // An untouched field of the same card is still topped up.
        let mut bare = after.clone();
        bare.monitoring = String::new();
        let cleared = db
            .conn
            .execute("UPDATE drugs SET monitoring = '' WHERE id = ?1", [after.id])
            .unwrap();
        assert_eq!(cleared, 1);
        db.fill_starter_details().unwrap();
        let refilled = db
            .drugs()
            .unwrap()
            .into_iter()
            .find(|d| d.name == "Eliquis")
            .unwrap();
        assert!(!refilled.monitoring.is_empty());
        assert!(refilled.ddi.is_empty());

        let _ = std::fs::remove_file(&path);
    }

